import path from 'path';
import { z } from 'zod';
import { GuidanceVerifierPackageSchema } from '../../types/guidance-verifier';
import {
  GuidanceReferenceNameSchema,
  GUIDANCE_REFERENCE_FILE_COUNT,
  GUIDANCE_REFERENCE_TOTAL_BYTES,
} from '../../types/guidance-references';
import { readGuidanceText } from './guidanceReferences';
const ManifestSchema = z
  .object({
    runtime: z.literal('node'),
    entrypoint: GuidanceReferenceNameSchema,
    files: z
      .array(
        z
          .object({
            name: GuidanceReferenceNameSchema,
            path: z.string().min(1),
          })
          .strict(),
      )
      .min(1)
      .max(GUIDANCE_REFERENCE_FILE_COUNT),
  })
  .strict();
export const guidanceVerifierPackage = async (manifestPath: string) => {
  const manifest = ManifestSchema.parse(
    JSON.parse(await readGuidanceText(manifestPath)),
  );
  const files = [];
  let totalBytes = 0;
  for (const file of manifest.files) {
    const content = await readGuidanceText(
      path.resolve(path.dirname(manifestPath), file.path),
    );
    totalBytes += Buffer.byteLength(content);
    if (totalBytes > GUIDANCE_REFERENCE_TOTAL_BYTES)
      throw new Error('Verifier package exceeds the 5 MiB text budget');
    files.push({ name: file.name, content });
  }
  return GuidanceVerifierPackageSchema.parse({ ...manifest, files });
};
